import AppKit
import Foundation
import ImageIO
import PounceKit

/// Decides what is never recorded (spec: Edge Cases): entries marked with the nspasteboard.org types
/// (concealed, transient, auto-generated) or the equivalent markers of password managers, entries
/// copied in an ignored app, and entries over 20 MB.
struct CaptureFilter: Sendable {
    /// 20 MB per entry; anything larger is skipped and logged.
    static let maximumEntryBytes = 20 << 20

    /// Marker types from nspasteboard.org and the private markers password managers still use.
    static let markerTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        // TypeIt4Me's legacy type name, and the dynamic identifier AppKit reports it as.
        "Pasteboard generator type",
        "dyn.agu8za2pxsvw0e55bsmwca35fr3w1e2pyr73ca7d3sbwu",
    ]

    /// Apps ignored by default (spec: Pasek menu i Ustawienia): Passwords, Keychain Access, 1Password,
    /// Bitwarden. Removing one is the user's choice; a release must never ignore fewer by default
    /// (`BACKWARD_COMPATIBILITY.md` section 3).
    static let defaultIgnoredApps = [
        "com.apple.Passwords",
        "com.apple.keychainaccess",
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.agilebits.onepassword-osx",
        "com.bitwarden.desktop",
    ]

    enum Skip: Equatable, Sendable {
        case markerType
        case ignoredApp
        case tooLarge
        case empty
    }

    let ignoredApps: Set<String>
    var maximumBytes = Self.maximumEntryBytes

    /// Checked before any data is read: marker types and the source app.
    func skipBeforeReading(types: [String], sourceBundleID: String?) -> Skip? {
        if types.contains(where: Self.markerTypes.contains) {
            return .markerType
        }
        if let sourceBundleID, ignoredApps.contains(sourceBundleID) {
            return .ignoredApp
        }
        if types.isEmpty {
            return .empty
        }
        return nil
    }

    /// Checked after the read: the size limit.
    func skipAfterReading(_ contents: PasteboardContents) -> Skip? {
        if contents.exceedsLimit || contents.byteCount > maximumBytes {
            return .tooLarge
        }
        if contents.items.allSatisfy({ $0.representations.isEmpty }) {
            return .empty
        }
        return nil
    }
}

/// Turns what was read from the pasteboard into an entry: the representations worth keeping, the kind
/// and the preview text. Runs off the main actor.
enum ClipClassifier {
    static let fileURLType = "public.file-url"
    static let urlType = "public.url"
    static let rtfType = "public.rtf"
    static let rtfdType = "com.apple.flat-rtfd"
    static let htmlType = "public.html"
    static let imageTypes: Set<String> = [
        "public.png", "public.tiff", "public.jpeg", "public.heic", "com.compuserve.gif", "org.webmproject.webp",
    ]

    /// Dynamic types (`dyn.…`) are app-private and opaque, and marker types carry no content.
    static func keeps(_ type: String) -> Bool {
        !type.hasPrefix("dyn.") && !CaptureFilter.markerTypes.contains(type)
    }

    static func draft(
        from contents: PasteboardContents,
        source: RunningApplication?,
        capturedAt: Date
    ) -> ClipDraft? {
        let items = contents.items
            .map { item in PasteboardItem(representations: item.representations.filter { keeps($0.type) }) }
            .filter { !$0.representations.isEmpty }
        guard let (kind, preview) = classify(items) else { return nil }
        return ClipDraft(
            kind: kind,
            previewText: preview,
            items: items,
            sourceBundleID: source?.bundleIdentifier,
            sourceAppName: source?.name,
            capturedAt: capturedAt
        )
    }

    /// The kind and preview text, or `nil` when no representation is one Pounce can show or paste.
    static func classify(_ items: [PasteboardItem]) -> (ClipKind, String)? {
        let types = Set(items.flatMap(\.types))
        let plain = items.lazy.compactMap { $0.data(for: PasteboardRepresentation.plainTextType) }.first
            .map { String(decoding: $0, as: UTF8.self) }

        let files = items.compactMap { $0.data(for: fileURLType).flatMap(url) }.filter(\.isFileURL)
        if !files.isEmpty {
            return (.file, files.map(\.path).joined(separator: "\n"))
        }
        if !types.isDisjoint(with: imageTypes), plain?.isEmpty ?? true {
            return (.image, imageSize(items).map { "\($0.width) × \($0.height)" } ?? "")
        }
        if let link = items.lazy.compactMap({ $0.data(for: urlType).flatMap(url) }).first, !link.isFileURL {
            return (.url, link.absoluteString)
        }
        if let plain, let link = webURL(plain) {
            return (.url, link.absoluteString)
        }
        if types.contains(rtfType) || types.contains(rtfdType) || types.contains(htmlType) {
            let text = plain ?? richText(items) ?? ""
            guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return nil }
            return (.rich, text)
        }
        if let plain, !plain.isEmpty {
            return (.text, plain)
        }
        return nil
    }

    /// A pasted text that is exactly one web address.
    static func webURL(_ text: String) -> URL? {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, !trimmed.contains(where: \.isWhitespace), trimmed.count <= 2048,
            let url = URL(string: trimmed), let scheme = url.scheme?.lowercased(),
            ["http", "https"].contains(scheme), url.host() != nil
        else { return nil }
        return url
    }

    private static func url(_ data: Data) -> URL? {
        let text = String(decoding: data, as: UTF8.self).trimmingCharacters(in: .whitespacesAndNewlines)
        return URL(string: text)
    }

    /// The pixel size of the first image representation (ImageIO, safe off the main thread).
    static func imageSize(_ items: [PasteboardItem]) -> (width: Int, height: Int)? {
        for item in items {
            for representation in item.representations where imageTypes.contains(representation.type) {
                guard let source = CGImageSourceCreateWithData(representation.data as CFData, nil),
                    let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any],
                    let width = properties[kCGImagePropertyPixelWidth] as? Int,
                    let height = properties[kCGImagePropertyPixelHeight] as? Int
                else { continue }
                return (width, height)
            }
        }
        return nil
    }

    /// Plain text of an RTF representation when the writer offered no plain text.
    private static func richText(_ items: [PasteboardItem]) -> String? {
        guard let data = items.lazy.compactMap({ $0.data(for: rtfType) }).first,
            let text = try? NSAttributedString(
                data: data,
                options: [.documentType: NSAttributedString.DocumentType.rtf],
                documentAttributes: nil
            )
        else { return nil }
        return text.string
    }
}
